def transform (grid :list [list [int ]])->list [list [int ]]:
    """
    # Diagnosis: The previous logic incorrectly filled 0-regions that were 
    # part of the background (exterior) or surrounded by multiple colors.
    """
    grid_arr =np .array (grid )
    rows ,cols =grid_arr .shape 
    output =grid_arr .copy ()

    # 8-connectivity structure for both objects and holes
    structure_8 =np .ones ((3 ,3 ))

    # Identify all 0-regions (potential holes)
    zero_mask =(grid_arr ==0 )
    labeled_zeros ,num_zeros =label (zero_mask ,structure =structure_8 )

    # To distinguish "holes" from "background", we find the background component.
    # The background is the 0-region that touches the grid boundary.
    background_mask =np .zeros_like (zero_mask )
    for i in range (1 ,num_zeros +1 ):
        coords =np .argwhere (labeled_zeros ==i )
        touches_boundary =False 
        for r ,c in coords :
            if r ==0 or r ==rows -1 or c ==0 or c ==cols -1 :
                touches_boundary =True 
                break 
        if touches_boundary :
            background_mask [labeled_zeros ==i ]=True 

            # Iterate through each 0-region
    for i in range (1 ,num_zeros +1 ):
    # If this 0-region is part of the background, skip it
        if background_mask [labeled_zeros ==i ].any ():
            continue 

        coords =np .argwhere (labeled_zeros ==i )

        # Check the colors of all non-zero neighbors surrounding this 0-region
        neighbor_colors =set ()
        for r ,c in coords :
            for dr in [-1 ,0 ,1 ]:
                for dc in [-1 ,0 ,1 ]:
                    if dr ==0 and dc ==0 :
                        continue 
                    nr ,nc =r +dr ,c +dc 
